def carry_headcount_over(apps, schema_editor):
    """Give every existing shop a staff row per unit of ``employee_count``.

    Capacity used to come from that integer. It now comes from the staff
    rows, so without this a shop with four barbers would drop to capacity
    one the moment the migration ran — a silent regression in a field no
    test would catch, because the tests create their own providers.

    The rows are placeholders. The names are not invented: a fabricated
    "Ravi" in a booking a customer can see is worse than an unnamed one,
    and the provider names them from the app.
    """
    Provider = apps.get_model("providers", "ProviderProfile")
    Staff = apps.get_model("providers", "Staff")

    for provider in Provider.objects.exclude(employee_count__lte=1).iterator():
        for index in range(1, provider.employee_count + 1):
            Staff.objects.create(
                provider_id=provider.pk,
                name=f"Staff member {index}",
                is_active=True,
                is_placeholder=True,
            )


